  "settings.amplifier.host.label": "IP-адрес усилителя",
  "settings.amplifier.host.hint": "Указан в меню NET IP ADDRESS усилителя KPA1500. Nexus работает с UDP-сервером усилителя, которым могут одновременно пользоваться сколько угодно программ, так что KPA1500 Remote от Elecraft может оставаться подключённой рядом.",
  "settings.amplifier.netPort.label": "Порт",
